mapper.select:
select pp.supplier_id, s.name as supplierName, pp.purchase_org_id as purchaseOrgId, pp.purchase_org_name as purchaseOrgName, ppd.currency, ppd.tax_price as taxPrice, ppd.tax_rate * 100 as taxRate, ppd.min_qty as minQty, ppd.max_qty as maxQty, ppd.delivery_day as deliveryDay from purchase_price pp inner join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false inner join supplier s on pp.supplier_id = s.id and s.is_deleted = false
pp.is_deleted = false and pp.approve_status = 'approve' and ppd.disabled = false and to_char(now(), 'yyyy-mm-dd')::TIMESTAMP >= ppd.effective_date and ppd.expire_date >= to_char(now(), 'yyyy-mm-dd')::TIMESTAMP
and ppd.sku_id = #{params.skuId}
and ppd.max_qty > #{params.purchaseQty} and #{params.purchaseQty} >= ppd.min_qty
and pp.supplier_id = #{params.supplierId}
and pp.purchase_org_id = #{params.purchaseOrgId}
order by pp.create_time desc

SELECT ppd.id, ppd.sku_id, ppd.delivery_day, ppd.min_qty, ppd.max_qty, ppd.currency, ppd.tax_price, ppd.tax_rate, ppd.effective_date, ppd.expire_date, ppd.disabled, pp.supplier_id FROM purchase_price_detail ppd inner join purchase_price pp on ppd.purchase_price_id = pp.id and pp.is_deleted = false WHERE ppd.is_deleted = FALSE AND pp.purchase_org_id = #{purchaseOrgId}
AND pp.supplier_id IN
#{item}
AND pp.approve_status IN
#{status}
AND ppd.sku_id IN
#{skuId}

