AND supplier_id IN
#{supplierId}
AND approve_status IN
#{status}
)
AND id NOT IN
#{id}
AND sku_id IN
#{skuId}

SELECT ppd.id, ppd.sku_id, ppd.delivery_day, ppd.min_qty, ppd.max_qty, ppd.currency, ppd.tax_price, ppd.tax_rate, ppd.disabled, pp.approve_status FROM purchase_price_detail ppd inner join purchase_price pp on pp.id = ppd.purchase_price_id WHERE ppd.is_deleted=FALSE AND pp.is_deleted=FALSE and pp.supplier_id = #{supplierId} and pp.purchase_org_id = #{purchaseOrgId}
AND pp.approve_status IN
#{status}

select pp.supplier_id, s.name as supplierName, ppd.sku_id as skuId, ppd.sku_no as skuNo, ppd.currency, ppd.tax_price as taxPrice, ppd.tax_rate * 100 as taxRate, ppd.min_qty as minQty, ppd.max_qty as maxQty, ppd.delivery_day as deliveryDay, pp.purchase_org_id as purchaseOrgId, pp.purchase_org_name as purchaseOrgName from purchase_price pp inner join purchase_price_detail ppd on pp.id = ppd.purchase_price_id and ppd.is_deleted = false inner join supplier s on pp.supplier_id = s.id and s.is_deleted = false
pp.is_deleted = false and pp.approve_status = 'approve' and ppd.disabled = false and to_char(now(), 'yyyy-mm-dd')::TIMESTAMP >= ppd.effective_date and ppd.expire_date >= to_char(now(), 'yyyy-mm-dd')::TIMESTAMP
and ppd.sku_id in
#{item}
and
(ppd.max_qty > #{item} and #{item} >= ppd.min_qty)
and pp.supplier_id in
#{item}
and pp.purchase_org_id in
#{item}

SELECT ppd.id, ppd.create_user_id, ppd.create_user_name, ppd.create_time, ppd.update_user_id, ppd.update_user_name, ppd.update_time, ppd.version, ppd.is_deleted, ppd.sku_id, ppd.purchase_price_id, ppd.sku_no, ppd.product_name, ppd.min_qty, ppd.max_qty, ppd.currency, ppd.tax_price, ppd.expire_date, ppd.tax_rate, ppd.delivery_day, ppd.effective_date, ppd.disabled, ppd.kingdee_detail_id, ppd.remark, pp.approve_status, pp.supplier_id, pp.code AS priceCode, pp.purchase_org_name FROM purchase_price_detail ppd inner join purchase_price pp on pp.id = ppd.purchase_price_id AND ppd.is_deleted = FALSE WHERE pp.is_deleted = FALSE
AND ppd.id IN
#{purchasePriceDetailId}
